import React, { useState, useEffect } from "react";
import { useDispatch } from "react-redux";
import { addJob } from "../Features/JobSlice";
import { useNavigate } from "react-router-dom";
import "../Styles/PostJob.css";

const PostJob = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // Protect route: only company can access
  useEffect(() => {
    const role = localStorage.getItem("role");
    if (role !== "company") navigate("/login");
  }, [navigate]);

  // Input states
  const [jobTitle, setJobTitle] = useState("");
  const [organization, setOrganization] = useState("");
  const [category, setCategory] = useState("");
  const [sector, setSector] = useState("");
  const [rate, setRate] = useState("");
  const [rateType, setRateType] = useState("");
  const [skills, setSkills] = useState("");
  const [description, setDescription] = useState("");
  const [payout, setPayout] = useState("");

  // Submit new job
  const handlePost = () => {
    if (!jobTitle || !organization || !rate) {
      alert("Please fill all required fields");
      return;
    }

    const jobData = {
      jobTitle,
      organization,
      category,
      sector,
      rate,
      rateType,
      skills,
      description,
      payout,
    };

    dispatch(addJob(jobData)); // Save job to MongoDB
    alert("Job posted successfully!");
  };

  return (
    <div className="postjob-page">
      <div className="postjob-container">
        <h1 className="postjob-title">
          Post a <span className="accent">Job</span>
        </h1>
        <p className="postjob-sub">Add a new job listing for students</p>

        <form className="postjob-form">
          <label>Job Title</label>
          <input
            type="text"
            placeholder="Graphic Designer"
            value={jobTitle}
            onChange={(e) => setJobTitle(e.target.value)}
          />

          <label>Organization</label>
          <input
            type="text"
            placeholder="Dhofar Advertising Co."
            value={organization}
            onChange={(e) => setOrganization(e.target.value)}
          />

          <div className="row-flex">
            <div className="col-half">
              <label>Category</label>
              <input
                type="text"
                placeholder="Design / Marketing"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              />
            </div>

            <div className="col-half">
              <label>Sector</label>
              <input
                type="text"
                placeholder="Private / Government"
                value={sector}
                onChange={(e) => setSector(e.target.value)}
              />
            </div>
          </div>

          <div className="row-flex">
            <div className="col-half">
              <label>Rate</label>
              <input
                type="number"
                placeholder="10"
                value={rate}
                onChange={(e) => setRate(e.target.value)}
              />
            </div>

            <div className="col-half">
              <label>Rate Type</label>
              <select
                value={rateType}
                onChange={(e) => setRateType(e.target.value)}
              >
                <option value="">Select type</option>
                <option value="Hour">Hour</option>
                <option value="Task">Task</option>
                <option value="Project">Project</option>
              </select>
            </div>
          </div>

          <label>Skills Required</label>
          <input
            type="text"
            placeholder="Photoshop, Canva, Social Media"
            value={skills}
            onChange={(e) => setSkills(e.target.value)}
          />

          <label>Description</label>
          <textarea
            placeholder="Explain job responsibilities and requirements"
            rows="4"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />

          <label>Payout (optional)</label>
          <input
            type="text"
            placeholder="e.g. After project completion"
            value={payout}
            onChange={(e) => setPayout(e.target.value)}
          />

          <button type="button" className="postjob-btn" onClick={handlePost}>
            Post Job
          </button>
        </form>
      </div>
    </div>
  );
};

export default PostJob;
